import {Address,
    Consignment,
    Country,
    Customer,
    CustomerAddress,
    FormField,} from '@bigcommerce/checkout-sdk'
import React, { Component, ReactNode } from 'react'
import { connect } from 'react-redux'
import B3Checkout from '../b3checkout'

import { TranslatedString } from '@bigcommerce/checkout/locale';
import { CheckoutContextProps } from '@bigcommerce/checkout/payment-integration-api';

import { AddressForm, AddressSelect, AddressType, isValidCustomerAddress } from '../address';
import { withCheckout } from '../checkout';
import { connectFormik, ConnectFormikProps } from '../common/form';
import { Fieldset } from '../ui/form';
import { LoadingOverlay } from '../ui/loading';

import { SingleShippingFormValues } from './SingleShippingForm'

export interface ShippingAddressFormProps {
    addresses: CustomerAddress[]
    address?: Address
    consignments: Consignment[]
    countries?: Country[]
    countriesWithAutocomplete: string[]
    customer: Customer
    googleMapsApiKey?: string
    isLoading: boolean
    formFields: FormField[]
    shouldShowSaveAddress?: boolean
    isFloatingLabelEnabled?: boolean;
    validateAddressFields: boolean;
    onUseNewAddress(): void;
    onFieldChange(fieldName: string, value: string): void;
    onAddressSelect(address: Address): void;
}

interface B3Props {
    isB3User: boolean
    checkoutSettings: any
}

interface WithCheckoutShippingAddressFormProps {
    customer: Customer;
}

const addressFieldName = 'shippingAddress'

class ShippingAddressForm extends Component<
    B3Props &
    ShippingAddressFormProps &
    ConnectFormikProps<SingleShippingFormValues>
> {
    validateAddress() {
        const {
            address: shippingAddress,
            addresses,
            formFields,
            validateAddressFields,
            isB3User,
        } = this.props

        if (!isB3User) return isValidCustomerAddress(
            shippingAddress,
            addresses,
            formFields,
            validateAddressFields,
        );

        const isValidateExtrasField = B3Checkout.extrasFiles.isValidExtrasFiles('shipping')
        return isValidateExtrasField && B3Checkout.utils.util.validateAddress(shippingAddress, addresses, formFields, validateAddressFields)
    }

    get shouldShowEnterNewAddress() {
        const { checkoutSettings } = this.props

        return checkoutSettings['shipping.address.add']
    }

    render(): ReactNode {
        const {
            addresses,
            address: shippingAddress,
            onAddressSelect,
            onUseNewAddress,
            shouldShowSaveAddress,
            countries,
            customer: { isGuest },
            countriesWithAutocomplete,
            formFields,
            isLoading,
            googleMapsApiKey,
            isFloatingLabelEnabled,
            formik: {
                values: { shippingAddress: formAddress },
                setFieldValue,
            },
            isB3User,
        } = this.props

        const hasAddresses = addresses && addresses.length > 0
        const hasValidCustomerAddress = this.validateAddress()

        return (
            <Fieldset id='checkoutShippingAddress'>
                { hasAddresses && (
                    <Fieldset id='shippingAddresses'>
                        <LoadingOverlay isLoading={ isLoading }>
                            <AddressSelect
                                addresses={ addresses }
                                onSelectAddress={ onAddressSelect }
                                onUseNewAddress={ onUseNewAddress }
                                selectedAddress={
                                    hasValidCustomerAddress ? shippingAddress : undefined
                                }
                                type={AddressType.Shipping}
                            />
                        </LoadingOverlay>
                    </Fieldset>
                ) }

                { this.shouldShowEnterNewAddress && !isGuest && (
                    <p>
                        <TranslatedString id='remote.or_text' />{ ' ' }
                        <a onClick={ onUseNewAddress }>
                            { B3Checkout.locales.tips['b3.addresses.enterNew'] }
                        </a>
                    </p>
                ) }

                { !hasValidCustomerAddress && (!isB3User || this.shouldShowEnterNewAddress) && (
                    <LoadingOverlay isLoading={ isLoading } unmountContentWhenLoading>
                        <AddressForm
                            countries={ countries }
                            countriesWithAutocomplete={ countriesWithAutocomplete }
                            countryCode={ formAddress && formAddress.countryCode }
                            fieldName={ addressFieldName }
                            formFields={ formFields }
                            googleMapsApiKey={ googleMapsApiKey }
                            isFloatingLabelEnabled={isFloatingLabelEnabled}
                            isLoadingB2bAddress={ true }
                            onAutocompleteToggle={ this.handleAutocompleteToggle }
                            onChange={ this.handleChange }
                            setFieldValue={ this.setFieldValue }
                            setShippingFieldValue={ setFieldValue }
                            shouldShowSaveAddress={ shouldShowSaveAddress }
                        />
                    </LoadingOverlay>
                ) }
            </Fieldset>
        )
    }

    private setFieldValue: (fieldName: string, fieldValue: string) => void = (
        fieldName,
        fieldValue,
    ) => {
        const {
            formik: { setFieldValue },
            formFields,
        } = this.props

        const customFormFieldNames = formFields
            .filter((field) => field.custom)
            .map((field) => field.name);

        const formFieldName = customFormFieldNames.includes(fieldName)
            ? `customFields.${fieldName}`
            : fieldName;

        setFieldValue(`${addressFieldName}.${formFieldName}`, fieldValue)
    }

    private handleChange: (fieldName: string, value: string) => void = (fieldName, value) => {
        const { onFieldChange } = this.props;

        onFieldChange(fieldName, value)
    }

    private handleAutocompleteToggle: (state: { inputValue: string; isOpen: boolean }) => void = ({
        isOpen,
        inputValue,
    }) => {
        const { onFieldChange } = this.props;

        if (!isOpen) {
            onFieldChange('address1', inputValue)
        }
    }
}

const mapStateToProps = (state: { global: { isB3User: boolean, checkoutSettings: any } }) => {
    const {
        global: { isB3User, checkoutSettings },
    } = state

    return {
        isB3User,
        checkoutSettings,
    }
}

function mapToShippingAddressProps({
    checkoutState,
}: CheckoutContextProps): WithCheckoutShippingAddressFormProps | null {
    const {
        data: {
            getCustomer,
        },
    } = checkoutState;

    const customer = getCustomer()

    if (!customer) return null

    return {
        customer
    }
}

export default connect(mapStateToProps)(connectFormik(withCheckout(mapToShippingAddressProps)(ShippingAddressForm)))