import {Address,
    Cart,
    CheckoutSelectors,
    Consignment,
    ConsignmentAssignmentRequestBody,
    Country,
    CustomerAddress,
    FormField,
    PhysicalItem,} from '@bigcommerce/checkout-sdk'
import { FormikProps, withFormik } from 'formik'
import { isEmpty } from 'lodash'
import React, { PureComponent, ReactNode } from 'react'
import { connect } from 'react-redux'
import { createSelector } from 'reselect'
import { lazy, object } from 'yup'

import { localizeAddress , TranslatedString, withLanguage, WithLanguageProps } from '@bigcommerce/checkout/locale';

import {AddressFormValues,
    getAddressFormFieldsValidationSchema,
    isValidAddress,} from '../../address'
import { withCheckout } from '../../checkout'
import { LocalizedGeography } from '../../geography'
import { OrderComments } from '../../orderComments'
import { AssignItemFailedError } from '../../shipping/errors'
import findLineItems from '../../shipping/findLineItems'
import hasSelectedShippingOptions from '../../shipping/hasSelectedShippingOptions'
import hasUnassignedLineItems from '../../shipping/hasUnassignedLineItems'
import ShippingAddressForm from '../../shipping/ShippingAddressForm'
import ShippingOptionsList from '../../shipping/shippingOption/ShippingOptionsList'
import StaticConsignmentItemList from '../../shipping/StaticConsignmentItemList'
import { Alert, AlertType } from '../../ui/alert'
import { Button, ButtonVariant } from '../../ui/button'
import { Fieldset, Form, TextInput } from '../../ui/form'
import { LoadingOverlay } from '../../ui/loading'
import extrasFiles from '../extrasFiles'
import { tips } from '../locales'
import { validateAddress } from '../utils/util'

import './styles.scss'

const createEmptyShippingAddress: () => Address = () => ({
    addressLine1: '',
    addressLine2: '',
    city: '',
    state: '',
    country: '',
    zipCode: '',
    firstName: '',
    lastName: '',
    customFields: [],
    company: '',
    address1: '',
    address2: '',
    stateOrProvince: '',
    stateOrProvinceCode: '',
    countryCode: '',
    postalCode: '',
    phone: '',
    shouldSaveAddress: false,
})

export interface MultiShippingFormProps {
    addresses: CustomerAddress[]
    cart: Cart
    isMultiShippingMode: boolean,
    cartHasChanged: boolean
    consignments: Consignment[]
    customerMessage: string
    isLoading: boolean
    shouldShowOrderComments: boolean
    onSubmit(values: MultiShippingFormValues): void
    onUnhandledError(error: Error): void
    onUseNewAddress(address: Address, itemId: string): void
    countriesWithAutocomplete: string[]
    getFields(countryCode?: string): FormField[]
    googleMapsApiKey?: string
    shouldShowSaveAddress?: boolean
    validateAddressFields: boolean;
}

export interface MultiShippingFormState {
    isEditing?: boolean
    fields?: FormField[]
    editConsignment: Consignment
    editingLineItems: Array<PhysicalItem & { rest?: number }>
    isConsignmentEditorOpen: boolean
}

interface WithCheckoutStaticAddressProps {
    countries?: Country[]
    isLoadingOption(consignmentId?: string): boolean
    selectShippingOption(
        consignmentId: string,
        optionId: string
    ): Promise<CheckoutSelectors>
    invalidShippingMessage: string
    deleteConsignment(consignmentId: string): Promise<CheckoutSelectors>
    assignItemsToAddress(
        consignment: ConsignmentAssignmentRequestBody
    ): Promise<CheckoutSelectors>
}

interface B3Props {
    checkoutSettings: any
}

interface PendingMultiShippingAddress {
    newAddress: Address & {
        addressId?: string;
        shouldSaveAddress?: boolean;
        company?: string;
    };
    billingSameAsShipping: boolean;
    isBillingMode: boolean;
    checkoutSettings: any;
    b2bCustomFields?: any;
    consignmentId: string;
}

class MultiShippingForm extends PureComponent<
    B3Props &
    WithCheckoutStaticAddressProps &
    MultiShippingFormProps &
    WithLanguageProps &
    FormikProps<MultiShippingFormValues>,
    MultiShippingFormState
    > {
    static getDerivedStateFromProps({ consignments }: MultiShippingFormProps) {
        if (!consignments.length)
            return {
                isConsignmentEditorOpen: true,
            }

        return null
    }

    state: MultiShippingFormState = {
        isConsignmentEditorOpen: false,
        editConsignment: {} as Consignment,
        editingLineItems: [],
    }

    constructor(
        props: B3Props &
            WithCheckoutStaticAddressProps &
            MultiShippingFormProps &
            WithLanguageProps &
            FormikProps<MultiShippingFormValues>
    ) {
        super(props)
    }

    componentDidMount() {
        const { consignments, cart } = this.props

        this.setState({
            isConsignmentEditorOpen: !consignments.length,
            editConsignment: this.basicConsignment,
            editingLineItems: findLineItems(cart, this.basicConsignment),
        })
    }

    get basicConsignment() {
        return {
            shippingAddress: createEmptyShippingAddress(),
            lineItemIds: this.getRestLineItemIds(),
        } as Consignment
    }

    get shouldShowConsignmentEditor() {
        const { cart, consignments } = this.props
        const { isConsignmentEditorOpen } = this.state

        return (
            isConsignmentEditorOpen ||
            hasUnassignedLineItems(consignments, cart.lineItems)
        )
    }

    render(): ReactNode {
        const {
            shouldShowOrderComments,
            isLoading,
            consignments,
            cartHasChanged,
            cart,
        } = this.props
        const { isConsignmentEditorOpen } = this.state

        return (
            <Form>
                <Fieldset
                    id='checkout-shipping-options'
                    legend={
                        <>
                            { cartHasChanged && (
                                <Alert type={ AlertType.Error }>
                                    <strong>
                                        <TranslatedString id='shipping.cart_change_error' />
                                    </strong>
                                </Alert>
                            ) }
                        </>
                    }
                >
                    { (!this.shouldShowConsignmentEditor ||
                        hasUnassignedLineItems(consignments, cart.lineItems)) &&
                        this.renderConsignments() }
                </Fieldset>

                { this.shouldShowConsignmentEditor && (
                    <>
                        { this.renderLineItemsEditor() }
                        { this.renderConsignmentEditor() }
                    </>
                ) }

                { !this.shouldShowConsignmentEditor && shouldShowOrderComments && (
                    <OrderComments />
                ) }

                <div className='form-actions'>
                    { this.shouldShowConsignmentEditor ? (
                        <>
                            <Button
                                disabled={ this.shouldDisableEditorSubmit() }
                                isLoading={ isLoading }
                                onClick={ this.handleEditorSubmit }
                                type='button'
                                variant={ ButtonVariant.Primary }
                            >
                                <TranslatedString id='common.continue_action' />
                            </Button>
                            { isConsignmentEditorOpen && (
                                <Button
                                    onClick={ this.handleEditorCancel }
                                    type='button'
                                    variant={ ButtonVariant.Secondary }
                                >
                                    <TranslatedString id='common.cancel_action' />
                                </Button>
                            ) }
                        </>
                    ) : (
                            <Button
                                disabled={ this.shouldDisableSubmit() }
                                id='checkout-shipping-continue'
                                isLoading={ isLoading }
                                onClick={ this.submit }
                                variant={ ButtonVariant.Primary }
                            >
                                <TranslatedString id='common.continue_action' />
                            </Button>
                    ) }
                </div>
            </Form>
        )
    }

    private submit = () => {
        const { onSubmit, values } = this.props

        onSubmit(values)
    }

    private handleEditorSubmit = async () => {
        const { editConsignment, editingLineItems } = this.state
        const { onUnhandledError, assignItemsToAddress, values, addresses, getFields, checkoutSettings, validateAddressFields } = this.props

        const { shippingAddress } = editConsignment

        if (!shippingAddress) return

        const formFields = getFields(shippingAddress && shippingAddress.countryCode)
        const isValid = validateAddress(shippingAddress, addresses, formFields, validateAddressFields)

        const {
            shippingAddress: {
                shouldSaveAddress,
                company
            },
            b2bCustomFields,
        } = values

        const lineItems = editingLineItems
            .map(({ id: itemId, quantity }) => ({
                itemId,
                quantity,
            }))
            .filter(({ quantity }) => !!quantity)

        try {
            if (checkoutSettings['shipping.address.save'] && shouldSaveAddress) {
                const storageKey = 'b3_pending_shipping_addresses';
                let pendingAddresses: PendingMultiShippingAddress[] = [];

                try {
                    const storedValue = sessionStorage.getItem(storageKey);

                    if (storedValue) {
                        const parsedValue = JSON.parse(storedValue);

                        if (Array.isArray(parsedValue)) {
                            pendingAddresses = parsedValue;
                        }
                    }
                } catch (error) {
                    console.warn('Failed to read pending multi-shipping addresses', error);
                }

                const nextPendingAddresses = pendingAddresses.filter(
                    (item) => item?.consignmentId !== editConsignment.id,
                );

                const pendingAddress = {
                    newAddress: {
                        ...shippingAddress,
                        addressId: isValid ? undefined : '',
                        shouldSaveAddress,
                        company,
                    },
                    billingSameAsShipping: false,
                    isBillingMode: false,
                    checkoutSettings,
                    b2bCustomFields,
                    consignmentId: editConsignment.id,
                };

                nextPendingAddresses.push(pendingAddress);
                sessionStorage.setItem(storageKey, JSON.stringify(nextPendingAddresses));
            }

            const assignToAddress = assignItemsToAddress({
                shippingAddress: {
                    ...shippingAddress,
                    company,
                },
                lineItems,
            })

            await assignToAddress
        } catch (error) {
            if (error instanceof Error) {
                onUnhandledError(new AssignItemFailedError(error))
            }
        }

        this.handleEditorCancel()
    }

    private handleEditorCancel = () => {
        const { cart } = this.props

        this.setState({
            isConsignmentEditorOpen: false,
            editConsignment: this.basicConsignment,
            editingLineItems: findLineItems(cart, this.basicConsignment),
        })
    }

    private handleEditorOpen = (consignment: Consignment) => () => {
        const { cart, setFieldValue } = this.props

        const lineItems = findLineItems(cart, consignment)

        this.setState(
            {
                isConsignmentEditorOpen: true,
                editConsignment: consignment,
                editingLineItems: lineItems,
            },
            () => setFieldValue('shippingAddress', consignment.shippingAddress)
        )
    }

    private shouldDisableEditorSubmit: () => boolean = () => {
        const { language, getFields, values: { b2bCustomFields } } = this.props
        const { editConsignment, editingLineItems } = this.state

        const { shippingAddress }: any = editConsignment
        const isShippingAddressValid =
            !!shippingAddress &&
            getAddressFormFieldsValidationSchema({
                language,
                formFields: getFields(shippingAddress.countryCode),
            }).isValidSync(shippingAddress)
       
        
        const  getB3ShippingFlieds = extrasFiles.getB3ShippingAddressExtras()
        let isExtrasValid = false

        if (getB3ShippingFlieds.length) {
            getB3ShippingFlieds.map((item: any) => {
                if (item.required && !b2bCustomFields[item.name]) {
                    isExtrasValid = true
                }
            })
        }

        const lineTotals = editingLineItems.reduce((result, lineItem) => result += lineItem.quantity, 0)

        return !isShippingAddressValid || !lineTotals || isExtrasValid
    }

    private shouldDisableSubmit: () => boolean = () => {
        const { isLoading, consignments, getFields, countries } = this.props

        const isAllValid = consignments.every(consignment => {
            const { shippingAddress } = consignment

            const fields = getFields(shippingAddress.countryCode)
            const address = localizeAddress(shippingAddress, countries)

            return !fields
                ? !isEmpty(address)
                : isValidAddress(
                    address,
                    fields.filter(field => !field.custom)
                )
        })

        return isLoading || !hasSelectedShippingOptions(consignments) || !isAllValid
    }

    renderConsignments(): ReactNode {
        const { consignments, getFields, countries, cart } = this.props

        if (!consignments.length) return null

        return (
            <div className='multi-consignments-container optimizedCheckout-overlay'>
                { consignments.map(consignment => {
                    const {
                        shippingAddress,
                        id,
                        selectedShippingOption,
                        availableShippingOptions,
                    } = consignment

                    const fields = getFields(shippingAddress.countryCode)
                    const address = localizeAddress(shippingAddress, countries)
                    const isValid = !fields
                        ? !isEmpty(address)
                        : isValidAddress(
                            address,
                            fields.filter(field => !field.custom)
                        )

                    return (
                        <div className='multi-address-listItem' key={ id }>
                            { this.renderStaticAddress(address, id, consignment) }

                            <StaticConsignmentItemList
                                cart={ cart }
                                consignment={ consignment }
                            />

                            { this.renderShippingOptionsList(
                                isValid,
                                id,
                                selectedShippingOption,
                                availableShippingOptions
                            ) }
                        </div>
                    )
                }) }
            </div>
        )
    }

    renderStaticAddress(
        address: Address & LocalizedGeography,
        id: string,
        consignment: Consignment
    ): ReactNode {
        return (
            <div className='checkout-address--static'>
                <div className='multi-address--info'>
                    { (address.firstName || address.lastName) && (
                        <p className='fn address-entry'>
                            <span className='first-name'>{ `${address.firstName} ` }</span>
                            <span className='family-name'>{ address.lastName }</span>
                        </p>
                    ) }

                    { (address.phone || address.company) && (
                        <p className='address-entry'>
                            <span className='company-name'>{ `${address.company} ` }</span>
                            <span className='tel'>{ address.phone }</span>
                        </p>
                    ) }

                    <div className='adr'>
                        <p className='street-address address-entry'>
                            <span className='address-line-1'>{ `${address.address1} ` }</span>
                            { address.address2 && (
                                <span className='address-line-2'>
                                    { ` / ${address.address2}` }
                                </span>
                            ) }
                        </p>

                        <p className='address-entry'>
                            { address.city && (
                                <span className='locality'>{ `${address.city}, ` }</span>
                            ) }
                            { address.localizedProvince && (
                                <span className='region'>{ `${address.localizedProvince}, ` }</span>
                            ) }
                            { address.postalCode && (
                                <span className='postal-code'>{ `${address.postalCode} / ` }</span>
                            ) }
                            { address.localizedCountry && (
                                <span className='country-name'>{ `${address.localizedCountry} ` }</span>
                            ) }
                        </p>
                    </div>
                </div>
                <div className='multi-address--actions'>
                    <a onClick={ this.handleEditorOpen(consignment) }>
                        { tips['b3.multiShipping.address.edit'] }
                    </a>
                    <a onClick={ this.handleDeleteConsignment(id) }>
                        { tips['b3.multiShipping.address.remove'] }
                    </a>
                </div>
            </div>
        )
    }

    private renderNoShippingOptions(message: ReactNode): ReactNode {
        return (
            <div className='shippingOptions-panel optimizedCheckout-overlay'>
                <p className='shippingOptions-panel-message optimizedCheckout-primaryContent'>
                    { message }
                </p>
            </div>
        )
    }

    private renderShippingOptionsList(
        isValid: boolean,
        id: string,
        selectedShippingOption: any,
        availableShippingOptions: any
    ): ReactNode {
        const {
            isLoadingOption,
            selectShippingOption,
            invalidShippingMessage,
            isMultiShippingMode,
        } = this.props

        if (!isValid) {
            return (
                <LoadingOverlay isLoading={ isLoadingOption() }>
                    { this.renderNoShippingOptions(
                        <TranslatedString id="shipping.select_shipping_address_text" />
                    ) }
                </LoadingOverlay>
            )
        }

        return (
            <>
                <ShippingOptionsList
                    consignmentId={ id }
                    inputName={ `shippingOptionIds.${id}` }
                    isLoading={ isLoadingOption(id) }
                    isMultiShippingMode= { isMultiShippingMode }
                    onSelectedOption={ selectShippingOption }
                    selectedShippingOptionId={
                        selectedShippingOption && selectedShippingOption.id
                    }
                    shippingOptions={ availableShippingOptions }
                />

                { (!availableShippingOptions || !availableShippingOptions.length) && (
                    <LoadingOverlay
                        hideContentWhenLoading
                        isLoading={ isLoadingOption(id) }
                    >
                        { this.renderNoShippingOptions(invalidShippingMessage) }
                    </LoadingOverlay>
                ) }
            </>
        )
    }

    handleDeleteConsignment = (id: string) => async () => {
        const { deleteConsignment } = this.props

        await deleteConsignment(id)
        this.handleEditorCancel()
    }

    renderConsignmentEditor(): ReactNode {
        const {
            addresses,
            countries,
            consignments,
            countriesWithAutocomplete,
            getFields,
            googleMapsApiKey,
            isLoading,
            shouldShowSaveAddress,
            validateAddressFields,
        } = this.props

        const {
            editConsignment: { shippingAddress },
        } = this.state

        return (
            <Fieldset>
                <ShippingAddressForm
                    address={ shippingAddress }
                    addresses={ addresses }
                    consignments={ consignments }
                    countries={ countries }
                    countriesWithAutocomplete={ countriesWithAutocomplete }
                    formFields={ getFields(shippingAddress && shippingAddress.countryCode) }
                    googleMapsApiKey={ googleMapsApiKey }
                    isLoading={ isLoading }
                    onAddressSelect={ this.handleSelectAddress }
                    onFieldChange={ this.handleFieldChange }
                    onUseNewAddress={ this.handleUseNewAddress }
                    shouldShowSaveAddress={ shouldShowSaveAddress }
                    validateAddressFields={validateAddressFields}
                />
            </Fieldset>
        )
    }

    private handleSelectAddress = (address: any) => {
        const { editConsignment } = this.state
        const { getFields } = this.props

        const shippingAddress = getFields(address.countryCode).reduce((result, { name, custom, }) => {
            if (custom) {
                const filed = address.customFields.find(({ fieldId }: { fieldId: string }) => fieldId === name);

                filed && result.customFields.push(filed)
            } else result[name] = address[name]

            return result
        }, {
            customFields: [],
            stateOrProvince: address.stateOrProvince,
        } as any)

        this.setState({
            editConsignment: {
                ...editConsignment,
                shippingAddress,
            } as Consignment,
        })
    }

    private handleFieldChange = async (name: string, value: any) => {
        const { editConsignment } = this.state
        const { setFieldValue } = this.props

        const { shippingAddress } = editConsignment

        this.setState({
            editConsignment: {
                ...editConsignment,
                shippingAddress: {
                    ...shippingAddress,
                    [name]: value,
                },
            } as Consignment,
        })

        if (name === 'countryCode') {
            setFieldValue('shippingAddress.stateOrProvince', '')
            setFieldValue('shippingAddress.stateOrProvinceCode', '')
        }

        // // Enqueue the following code to run after Formik has run validation
        await new Promise(resolve => setTimeout(resolve))

        // const { isValid } = this.props
    }

    private handleUseNewAddress = () => {
        const { setFieldValue } = this.props

        this.setState(
            {
                editConsignment: {
                    ...this.basicConsignment,
                } as Consignment,
            },
            () =>
                setFieldValue('shippingAddress', this.basicConsignment.shippingAddress)
        )
    }

    private renderLineItemsEditor(): ReactNode {
        const { editingLineItems: lineItems } = this.state

        return (
            <div className='multi-line-items-editor-container optimizedCheckout-overlay'>
                { lineItems.map(lineItem => (
                    <div className='multi-line-item' key={ lineItem.id }>
                        <figure className='product-figure'>
                            <img src={ lineItem.imageUrl } />
                        </figure>
                        <span>{ lineItem.name } </span>
                        <span dangerouslySetInnerHTML={ { __html: ' &times;' } } />
                        <div className='multi-line-item-input'>
                            <TextInput
                                onChange={ this.setLineItemQuantity(lineItem.id) }
                                value={ lineItem.quantity }
                            />
                        </div>
                        <span>
                            { lineItem?.rest || 0 } { tips['b3.multiShipping.shipped.toAddress'] }
                        </span>
                    </div>
                )) }
            </div>
        )
    }

    private getRestLineItemIds() {
        const { consignments, cart } = this.props

        if (!hasUnassignedLineItems(consignments, cart.lineItems)) return []

        return cart.lineItems.physicalItems
            .filter(
                ({ id, addedByPromotion }) =>
                    !addedByPromotion &&
                    !consignments.some(consignment =>
                        consignment.lineItemIds.includes(id as string)
                    )
            )
            .map(({ id }) => id)
    }

    private setLineItemQuantity = (id: string | number) => (
        e: React.ChangeEvent<HTMLInputElement>
    ) => {
        const { editingLineItems } = this.state
        const { cart } = this.props

        const physicalItem = cart.lineItems.physicalItems.find(
            item => item.id === id
        )

        if (!physicalItem) return

        const { quantity } = physicalItem

        const newEditingLineItems = editingLineItems.map(lineItem => {
            let { quantity: newQuantity, rest = 0 } = lineItem

            if (lineItem.id === id) {
                const value = +e.target.value

                newQuantity = Math.max(
                    Math.min(quantity, isNaN(value) ? newQuantity : value),
                    0
                )
                rest = quantity - newQuantity
            }

            return {
                ...lineItem,
                quantity: newQuantity,
                rest,
            }
        })

        this.setState({
            editingLineItems: newEditingLineItems,
        })
    }
}

export interface MultiShippingFormValues {
    [x: string]: any
    orderComment: string
}

const isLoadingSelector = createSelector(
    (_: CheckoutSelectors, { isLoading }: MultiShippingFormProps) => isLoading,
    ({ statuses }: CheckoutSelectors) => statuses.isLoadingShippingOptions,
    ({ statuses }: CheckoutSelectors) => statuses.isSelectingShippingOption,
    ({ statuses }: CheckoutSelectors) => statuses.isUpdatingConsignment,
    ({ statuses }: CheckoutSelectors) => statuses.isCreatingConsignments,
    (
        isLoading,
        isLoadingShippingOptions,
        isSelectingShippingOption,
        isUpdatingConsignment,
        isCreatingConsignments
    ) => {
        return (consignmentId?: string) => {
            return (
                isLoading ||
                isLoadingShippingOptions() ||
                isSelectingShippingOption(consignmentId) ||
                isUpdatingConsignment(consignmentId) ||
                isCreatingConsignments()
            )
        }
    }
)

export function mapToStaticAddressProps(
    { checkoutService, checkoutState }: any,
    props: MultiShippingFormProps
): WithCheckoutStaticAddressProps | null {
    const {
        data: { getShippingCountries, getConfig },
    } = checkoutState

    const config = getConfig()

    if (!config) return null

    const { shippingQuoteFailedMessage } = config.checkoutSettings

    return {
        countries: getShippingCountries(),
        isLoadingOption: isLoadingSelector(checkoutState, props),
        selectShippingOption: checkoutService.selectConsignmentShippingOption,
        invalidShippingMessage: shippingQuoteFailedMessage,
        deleteConsignment: checkoutService.deleteConsignment,
        assignItemsToAddress: checkoutService.assignItemsToAddress,
    }
}

const mapStateToProps = (state: { global: { checkoutSettings: any }, company: any }) => {
    const {
        global: {
            checkoutSettings,
        },
    } = state

    return {
        checkoutSettings,
    }
}

export default connect(mapStateToProps)(
    withLanguage(
        withFormik<
            MultiShippingFormProps & WithLanguageProps & B3Props,
            MultiShippingFormValues
        >({
            handleSubmit: (values, { props: { onSubmit } }) => {
                onSubmit(values)
            },
            mapPropsToValues: ({ customerMessage, consignments }) => {
                const shippingOptionIds: { [id: string]: string } = {}

                    ; (consignments || []).forEach(consignment => {
                        shippingOptionIds[consignment.id] = consignment.selectedShippingOption
                            ? consignment.selectedShippingOption.id
                            : ''
                    })

                return {
                    orderComment: customerMessage,
                    shippingOptionIds,
                    shippingAddress: createEmptyShippingAddress(),
                    b2bCustomFields: extrasFiles.setGoBackEcho('shipping')
                }
            },
            validationSchema: ({
                language,
                getFields,
            }: MultiShippingFormProps & WithLanguageProps) =>
                object({
                    shippingAddress: lazy<Partial<AddressFormValues>>(formValues =>
                        getAddressFormFieldsValidationSchema({
                            language,
                            formFields: getFields(formValues && formValues.countryCode),
                        })
                    ),
                    b2bCustomFields: lazy<Partial<any>>( () =>
                        extrasFiles.getB3FormFieldsValidationSchema({
                                translate: extrasFiles.getTranslateAddressError(language),
                                formFields: extrasFiles.getB3ShippingAddressExtras(),
                            })
                        ),
                }),
            enableReinitialize: true,
        })(withCheckout(mapToStaticAddressProps)(MultiShippingForm))
    )
)
